// Checks the extension manifest and the generated brand assets without needing
// the VS Code toolchain.
//
//   node scripts/verify-extension.js
//
// Run with `npm run verify` inside this directory. Exits non-zero when
// something an editor, the marketplace or GitHub needs is missing.
//
// Everything below is regenerated by scripts/make-brand-assets.ps1 at the repo
// root, so a failure here usually means that script has not been run after
// changing favicon.ico.

const fs = require('fs');
const path = require('path');

const root = path.resolve(__dirname, '..');
const repoRoot = path.resolve(root, '..', '..');
const problems = [];

function check(condition, message) {
  if (!condition) {
    problems.push(message);
  }
}

// Reads width/height straight out of the PNG IHDR chunk, so no image library
// or native module is needed.
function pngSize(file) {
  const signature = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
  const bytes = fs.readFileSync(file);
  if (bytes.length < 24 || !bytes.subarray(0, 8).equals(signature)) {
    return null;
  }
  return { width: bytes.readUInt32BE(16), height: bytes.readUInt32BE(20) };
}

function checkPng(relativePath, expect, base) {
  const file = path.isAbsolute(relativePath) ? relativePath : path.join(base || root, relativePath);
  if (!fs.existsSync(file)) {
    problems.push(`${relativePath} is missing`);
    return;
  }
  const size = pngSize(file);
  if (!size) {
    problems.push(`${relativePath} is not a valid PNG`);
    return;
  }
  if (expect.width && size.width !== expect.width) {
    problems.push(`${relativePath} is ${size.width}px wide, expected ${expect.width}px`);
  }
  if (expect.height && size.height !== expect.height) {
    problems.push(`${relativePath} is ${size.height}px tall, expected ${expect.height}px`);
  }
}

const manifestPath = path.join(root, 'package.json');
check(fs.existsSync(manifestPath), 'package.json is missing');
if (!fs.existsSync(manifestPath)) {
  report();
}

const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));

check(typeof manifest.name === 'string' && manifest.name.length > 0, 'name is missing');
check(/^\d+\.\d+\.\d+$/.test(manifest.version || ''), 'version must be semver');
check(
  typeof manifest.engines?.vscode === 'string' || Array.isArray(manifest.engines?.vscode),
  'engines.vscode must declare a VS Code range'
);

// The marketplace rejects icons that are missing, tiny or not square.
const icon = manifest.icon ? path.join(root, manifest.icon) : null;
if (icon) {
  check(fs.existsSync(icon), `icon ${manifest.icon} is missing`);
  if (fs.existsSync(icon)) {
    const size = pngSize(icon);
    check(!!size, `icon ${manifest.icon} must be a PNG`);
    if (size) {
      check(size.width === size.height, `icon ${manifest.icon} must be square`);
      check(size.width >= 128, `icon ${manifest.icon} must be at least 128x128`);
    }
  }
} else {
  check(false, 'no top-level icon (the marketplace requires one)');
}

// The marketplace banner has a fixed recommended size; a wrong one is silently
// letterboxed, so it is checked here rather than discovered after publishing.
if (manifest.galleryBanner) {
  checkPng(manifest.galleryBanner, { width: 1280, height: 600 });
}

// The rest of the generated brand set. These are not read by VS Code, but the
// README and the GitHub social preview point at them, so a missing or resized
// file is a broken link rather than a cosmetic issue.
for (const size of [32, 64, 128]) {
  checkPng(`icons/nxl-${size}.png`, { width: size, height: size });
}
checkPng(path.join('.github', 'assets', 'nexora-preview.png'), { width: 1280, height: 640 }, repoRoot);
checkPng(path.join('dist-brand', 'nxl-logo.png'), { width: 512, height: 512 }, repoRoot);

const svgIcon = path.join(root, 'icons', 'nxl.svg');
if (!fs.existsSync(svgIcon)) {
  problems.push('icons/nxl.svg is missing');
} else {
  const svg = fs.readFileSync(svgIcon, 'utf8');
  check(svg.includes('viewBox'), 'icons/nxl.svg has no viewBox');
  check(
    svg.includes('data:image/png;base64,'),
    'icons/nxl.svg should embed the generated logo so it renders with no build step'
  );
}

const language = (manifest.contributes?.languages || [])[0];
check(!!language, 'contributes.languages is empty');
if (language) {
  check(language.id === 'nxl', 'the language id should be "nxl"');
  check(
    (language.extensions || []).includes('.nxl'),
    'the language must claim the .nxl extension'
  );
  check(
    typeof language.icon === 'string',
    'the language needs an icon for the file explorer'
  );
  if (language.icon) {
    const fileIcon = path.join(root, language.icon);
    check(fs.existsSync(fileIcon), `language icon ${language.icon} is missing`);
    // VS Code renders language icons as SVG or PNG; .ico is not supported.
    check(
      /\.(svg|png)$/i.test(language.icon),
      `language icon must be .svg or .png, not ${language.icon}`
    );
  }
}

const grammar = (manifest.contributes?.grammars || [])[0];
check(!!grammar, 'contributes.grammars is empty');
if (grammar) {
  check(fs.existsSync(path.join(root, grammar.path)), `${grammar.path} is missing`);
  if (fs.existsSync(path.join(root, grammar.path))) {
    JSON.parse(fs.readFileSync(path.join(root, grammar.path), 'utf8'));
  }
}

if (language?.configuration) {
  check(
    fs.existsSync(path.join(root, language.configuration)),
    `${language.configuration} is missing`
  );
}

for (const command of manifest.contributes?.commands || []) {
  check(typeof command.command === 'string', 'a command has no id');
  check(typeof command.title === 'string', `command ${command.command} has no title`);
}

if (fs.existsSync(path.join(root, 'extension.js'))) {
  const source = fs.readFileSync(path.join(root, 'extension.js'), 'utf8');
  // eslint-disable-next-line no-new-func
  new Function('require', 'module', 'exports', source);
}

// The extension's language client is the same story: it must exist and parse,
// and extension.js must actually use it. A client left unwired would look fine
// on disk while the editor quietly offered no completion at all.
const clientPath = path.join(root, 'language-client.js');
check(fs.existsSync(clientPath), 'language-client.js is missing');
if (fs.existsSync(clientPath)) {
  const client = fs.readFileSync(clientPath, 'utf8');
  // eslint-disable-next-line no-new-func
  new Function('require', 'module', 'exports', client);
  for (const piece of ['Content-Length', 'textDocument/publishDiagnostics', 'request']) {
    check(
      client.includes(piece),
      `language-client.js does not look like an LSP client: no ${piece}`
    );
  }
  if (fs.existsSync(path.join(root, 'extension.js'))) {
    const source = fs.readFileSync(path.join(root, 'extension.js'), 'utf8');
    check(
      source.includes("require('./language-client')"),
      'extension.js does not load the language client'
    );
    for (const feature of [
      'registerCompletionItemProvider',
      'registerHoverProvider',
      'registerDefinitionProvider',
      'createDiagnosticCollection',
    ]) {
      check(source.includes(feature), `extension.js does not register ${feature}`);
    }
  }
}

function report() {
  if (problems.length > 0) {
    console.error('extension verification failed:');
    for (const problem of problems) {
      console.error(`  - ${problem}`);
    }
    process.exit(1);
  }
  console.log('extension manifest verified');
  process.exit(0);
}

report();